transformed parameters {
  matrix[I, J] y;
  for (n in 1:N_obs)
    y[ii_obs[n], jj_obs[n]] = y_obs[n];
  for (n in 1:_N_un)
    y[ii_un[n], jj_un[n]] = y_un[n];

